package br.com.admeclesial.domain.organizacao;
import jakarta.persistence.*; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="vinculo_funcao_eclesial",schema="adm_eclesial") public class VinculoFuncaoEclesial {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true,updatable=false) private UUID uuid; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="vinculo_pessoa_organizacao_id",nullable=false) private VinculoPessoaOrganizacaoEclesial vinculoPessoaOrganizacao; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="funcao_eclesial_id",nullable=false) private FuncaoEclesial funcaoEclesial; @Column(name="data_inicio",nullable=false) private LocalDate dataInicio; @Column(name="data_fim") private LocalDate dataFim; @Column(nullable=false) private boolean principal; @Column(columnDefinition="text") private String observacao;
 @PrePersist void prePersist(){if(uuid==null)uuid=UUID.randomUUID();}
 public Long getId(){return id;} public UUID getUuid(){return uuid;} public void setVinculoPessoaOrganizacao(VinculoPessoaOrganizacaoEclesial v){vinculoPessoaOrganizacao=v;} public void setFuncaoEclesial(FuncaoEclesial v){funcaoEclesial=v;} public void setDataInicio(LocalDate v){dataInicio=v;} public void setDataFim(LocalDate v){dataFim=v;} public void setPrincipal(boolean v){principal=v;} public void setObservacao(String v){observacao=v;} public VinculoPessoaOrganizacaoEclesial getVinculoPessoaOrganizacao(){return vinculoPessoaOrganizacao;} public FuncaoEclesial getFuncaoEclesial(){return funcaoEclesial;} public LocalDate getDataInicio(){return dataInicio;} public LocalDate getDataFim(){return dataFim;} public boolean isPrincipal(){return principal;} public String getObservacao(){return observacao;}
}
